import json
import sys

content = sys.stdin.read()
try:
    data = json.loads(content)
    if isinstance(data, str):
        experiments = json.loads(data)
    else:
        experiments = data
except:
    print("Parse error")
    sys.exit(1)

if not isinstance(experiments, list):
    experiments = list(experiments.values()) if isinstance(experiments, dict) else []

# Filter: conclusion=success, 0.6B training, westd-41312
missing_evals = []

for exp in experiments:
    if exp.get("conclusion") != "success":
        continue
    if exp.get("server") != "westd-41312":
        continue
    # Skip eval-only (no "train_loss" in description typically)
    spec = exp.get("spec", {})
    if "0.6B" not in str(spec) and "0.6B" not in exp.get("description", ""):
        continue

    metrics = exp.get("metrics", {})
    has_downstream = any(k.startswith("downstream_arc") for k in metrics.keys())
    has_ood = any(k.startswith("eval_ppl_") for k in metrics.keys())

    if not has_downstream and not has_ood:
        missing_evals.append({
            "exp_id": exp.get("exp_id"),
            "has_any_metrics": bool(metrics),
            "metric_keys": list(metrics.keys())[:3]
        })

print(json.dumps(missing_evals, indent=2))
EOF
